function se = ElementLaplacianMatrix_FR(nnpe,nqptv,wtq,qpmetric,bigNprime,detj,gij_matrix)% % called by OrMonics%% forms elemental stiffness matrix for solving the negative Laplacian over% the fundamental region of orientation spacese = zeros(nnpe,nnpe);                                       for   k=1:1:nqptv       bigNprimeqp = bigNprime(:,:,k);    qp_gij_matrix(:,:) = gij_matrix(:,:,k);                                     xkfac(k)=wtq(k)*detj(k)*qpmetric(k);        se = se + xkfac(k)*(bigNprimeqp'  * qp_gij_matrix * bigNprimeqp);      end